import re
import sys

# Increase recursion depth to accommodate reference chains spanning up to 2574 cells
sys.setrecursionlimit(20000)


def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    TOKEN_REGEX = re.compile(
        r"\s*([A-Z]\d{1,2}:[A-Z]\d{1,2}|<=|>=|<>|[A-Z]\d{1,2}|[A-Za-z]+|\d+|[=+\-*/(),<>])"
    )

    def parse_cell_name(name: str) -> tuple[int, int]:
        return ord(name[0]) - ord("A"), int(name[1:])

    # AST Nodes
    class IntLit:
        __slots__ = ("val",)

        def __init__(self, val: int):
            self.val = val

    class CellRef:
        __slots__ = ("name",)

        def __init__(self, name: str):
            self.name = name

    class UnaryOp:
        __slots__ = ("op", "expr")

        def __init__(self, op: str, expr):
            self.op = op
            self.expr = expr

    class BinOp:
        __slots__ = ("op", "left", "right")

        def __init__(self, op: str, left, right):
            self.op = op
            self.left = left
            self.right = right

    class RangeArg:
        __slots__ = ("cells",)

        def __init__(self, c1: str, c2: str):
            col1, row1 = parse_cell_name(c1)
            col2, row2 = parse_cell_name(c2)
            min_col, max_col = min(col1, col2), max(col1, col2)
            min_row, max_row = min(row1, row2), max(row1, row2)
            # Row-major order: top row first, left to right within row
            res = []
            for r in range(min_row, max_row + 1):
                for c in range(min_col, max_col + 1):
                    res.append(f"{chr(ord('A') + c)}{r}")
            self.cells = res

    class FuncCall:
        __slots__ = ("name", "args")

        def __init__(self, name: str, args: list):
            self.name = name
            self.args = args

    class IfCall:
        __slots__ = ("op", "left", "right", "then_branch", "else_branch")

        def __init__(self, op: str, left, right, then_branch, else_branch):
            self.op = op
            self.left = left
            self.right = right
            self.then_branch = then_branch
            self.else_branch = else_branch

    # Parser
    class Parser:
        def __init__(self, tokens: list[str]):
            self.tokens = tokens
            self.pos = 0

        def peek(self) -> str | None:
            return self.tokens[self.pos] if self.pos < len(self.tokens) else None

        def advance(self) -> str:
            tok = self.tokens[self.pos]
            self.pos += 1
            return tok

        def expect(self, expected: str):
            tok = self.advance()
            if tok != expected:
                raise ValueError(f"Expected {expected}, got {tok}")

        def parse(self):
            expr = self.parse_additive()
            return expr

        def parse_additive(self):
            left = self.parse_multiplicative()
            while self.peek() in ("+", "-"):
                op = self.advance()
                right = self.parse_multiplicative()
                left = BinOp(op, left, right)
            return left

        def parse_multiplicative(self):
            left = self.parse_unary()
            while self.peek() in ("*", "/"):
                op = self.advance()
                right = self.parse_unary()
                left = BinOp(op, left, right)
            return left

        def parse_unary(self):
            if self.peek() == "-":
                op = self.advance()
                operand = self.parse_unary()
                return UnaryOp(op, operand)
            return self.parse_atom()

        def parse_atom(self):
            tok = self.peek()
            if tok is None:
                raise ValueError("Unexpected end of tokens")

            if tok == "(":
                self.advance()
                expr = self.parse_additive()
                self.expect(")")
                return expr

            if tok.isdigit():
                self.advance()
                return IntLit(int(tok))

            # Function call
            if tok in ("SUM", "MIN", "MAX"):
                func_name = self.advance()
                self.expect("(")
                args = []
                while True:
                    # An argument can be a Range (e.g. A1:B3) or a formula
                    curr = self.peek()
                    if curr and ":" in curr:
                        self.advance()
                        c1, c2 = curr.split(":")
                        args.append(RangeArg(c1, c2))
                    else:
                        args.append(self.parse_additive())

                    if self.peek() == ",":
                        self.advance()
                    else:
                        break
                self.expect(")")
                return FuncCall(func_name, args)

            if tok == "IF":
                self.advance()
                self.expect("(")
                left = self.parse_additive()
                op = self.advance()  # =, <>, <, <=, >, >=
                right = self.parse_additive()
                self.expect(",")
                then_branch = self.parse_additive()
                self.expect(",")
                else_branch = self.parse_additive()
                self.expect(")")
                return IfCall(op, left, right, then_branch, else_branch)

            # Cell reference (e.g., A1)
            self.advance()
            return CellRef(tok)

    # Parsing the whole sheet
    parsed_cells = {}
    for name, content in cells.items():
        content_str = content.strip()
        # Direct integer literal without '='
        is_direct_int = False
        try:
            val = int(content_str)
            is_direct_int = True
        except ValueError:
            pass

        if is_direct_int:
            parsed_cells[name] = IntLit(int(content_str))
        else:
            formula = content_str
            if formula.startswith("="):
                formula = formula[1:]
            tokens = TOKEN_REGEX.findall(formula)
            parser = Parser(tokens)
            parsed_cells[name] = parser.parse()

    # Evaluation state:
    # 0 = not visited, 1 = visiting, 2 = done
    state: dict[str, int] = {}
    values: dict[str, int | str] = {}

    def is_error(val: int | str) -> bool:
        return isinstance(val, str)

    def eval_node(node) -> int | str:
        if isinstance(node, IntLit):
            return node.val

        elif isinstance(node, CellRef):
            return eval_cell(node.name)

        elif isinstance(node, UnaryOp):
            val = eval_node(node.expr)
            if is_error(val):
                return val
            return -val

        elif isinstance(node, BinOp):
            l = eval_node(node.left)
            if is_error(l):
                return l
            r = eval_node(node.right)
            if is_error(r):
                return r
            if node.op == "+":
                return l + r
            elif node.op == "-":
                return l - r
            elif node.op == "*":
                return l * r
            elif node.op == "/":
                if r == 0:
                    return "#DIV/0!"
                # Integer division truncating toward zero
                return int(l / r)

        elif isinstance(node, FuncCall):
            collected_values = []
            for arg in node.args:
                if isinstance(arg, RangeArg):
                    for c_name in arg.cells:
                        if c_name in cells:
                            val = eval_cell(c_name)
                            if is_error(val):
                                return val
                            collected_values.append(val)
                else:
                    val = eval_node(arg)
                    if is_error(val):
                        return val
                    collected_values.append(val)

            if node.name == "SUM":
                return sum(collected_values)
            elif node.name == "MIN":
                return min(collected_values) if collected_values else 0
            elif node.name == "MAX":
                return max(collected_values) if collected_values else 0

        elif isinstance(node, IfCall):
            l = eval_node(node.left)
            if is_error(l):
                return l
            r = eval_node(node.right)
            if is_error(r):
                return r

            cond = False
            if node.op == "=":
                cond = l == r
            elif node.op == "<>":
                cond = l != r
            elif node.op == "<":
                cond = l < r
            elif node.op == "<=":
                cond = l <= r
            elif node.op == ">":
                cond = l > r
            elif node.op == ">=":
                cond = l >= r

            if cond:
                return eval_node(node.then_branch)
            else:
                return eval_node(node.else_branch)

        return 0

    def eval_cell(name: str) -> int | str:
        if name not in cells:
            return 0
        if state.get(name) == 2:
            return values[name]
        if state.get(name) == 1:
            return "#CYCLE!"

        state[name] = 1
        val = eval_node(parsed_cells[name])
        values[name] = val
        state[name] = 2
        return val

    # Evaluate every cell present in `cells`
    for name in cells:
        eval_cell(name)

    return {name: values[name] for name in cells}
